import { test, expect } from '@playwright/test';

test.describe('Lazy-loaded components smooth appearance without layout shift', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should load lazy components without causing layout shift', async ({ page }) => {
    // Get initial viewport dimensions
    const initialViewportSize = page.viewportSize();
    expect(initialViewportSize).toBeTruthy();

    // Wait for the page to be fully loaded
    await page.waitForLoadState('networkidle');

    // Get the initial scroll height
    const initialScrollHeight = await page.evaluate(() => document.documentElement.scrollHeight);

    // Scroll to trigger lazy loading
    await page.evaluate(() => window.scrollBy(0, window.innerHeight));

    // Wait for lazy-loaded components to appear
    const lazyComponents = page.getByRole('region', { name: /lazy-loaded/i });
    await expect(lazyComponents).toBeVisible({ timeout: 5000 });

    // Check that scroll height hasn't changed significantly (no layout shift)
    const finalScrollHeight = await page.evaluate(() => document.documentElement.scrollHeight);
    const heightDifference = Math.abs(finalScrollHeight - initialScrollHeight);

    // Allow minimal height difference (less than 50px for smooth loading)
    expect(heightDifference).toBeLessThan(50);

    // Verify components are rendered smoothly
    const loadedItems = page.getByRole('article');
    const itemCount = await loadedItems.count();
    expect(itemCount).toBeGreaterThan(0);
  });

  test('should display lazy-loaded images with proper dimensions before loading', async ({ page }) => {
    await page.goto('https://example.com');
    await page.waitForLoadState('networkidle');

    // Find lazy-loaded image containers
    const imageContainers = page.getByRole('img');

    // Get the first image container's bounding box
    const firstImage = imageContainers.first();
    const initialBox = await firstImage.boundingBox();
    expect(initialBox).toBeTruthy();
    expect(initialBox?.width).toBeGreaterThan(0);
    expect(initialBox?.height).toBeGreaterThan(0);

    // Scroll to trigger image lazy loading
    await page.evaluate(() => window.scrollBy(0, window.innerHeight));

    // Wait for image to load
    await expect(firstImage).toHaveAttribute('src', /^(?!data:)/, { timeout: 5000 });

    // Get the final bounding box after loading
    const finalBox = await firstImage.boundingBox();
    expect(finalBox).toBeTruthy();

    // Verify dimensions remain consistent (no layout shift)
    expect(finalBox?.width).toBe(initialBox?.width);
    expect(finalBox?.height).toBe(initialBox?.height);
    expect(finalBox?.x).toBe(initialBox?.x);
    expect(finalBox?.y).toBe(initialBox?.y);
  });

  test('should maintain smooth scrolling experience while lazy components load', async ({ page }) => {
    await page.goto('https://example.com');
    await page.waitForLoadState('networkidle');

    // Record initial scroll position
    const initialScrollPosition = await page.evaluate(() => window.scrollY);

    // Perform smooth scroll
    await page.evaluate(() => {
      window.scrollBy({ top: window.innerHeight, behavior: 'smooth' });
    });

    // Wait for lazy components to load
    await page.waitForTimeout(1000);

    // Verify scroll position has changed
    const currentScrollPosition = await page.evaluate(() => window.scrollY);
    expect(currentScrollPosition).toBeGreaterThan(initialScrollPosition);

    // Check that lazy-loaded content is visible
    const lazyContent = page.getByRole('main');
    await expect(lazyContent).toBeVisible();

    // Verify no cumulative layout shift by checking element positions
    const elements = page.getByRole('heading');
    const firstElementBox = await elements.first().boundingBox();
    expect(firstElementBox).toBeTruthy();
    expect(firstElementBox?.y).toBeGreaterThanOrEqual(0);
  });

  test('should load multiple lazy components sequentially without blocking UI', async ({ page }) => {
    await page.goto('https://example.com');
    await page.waitForLoadState('networkidle');

    // Get all lazy-loadable sections
    const sections = page.getByRole('region');
    const sectionCount = await sections.count();

    // Scroll through multiple sections
    for (let i = 0; i < Math.min(sectionCount, 3); i++) {
      await page.evaluate(() => window.scrollBy(0, window.innerHeight));
      await page.waitForTimeout(500);

      // Verify page remains responsive by checking if elements are still accessible
      const visibleElements = page.getByRole('button');
      const buttonCount = await visibleElements.count();
      expect(buttonCount).toBeGreaterThanOrEqual(0);
    }

    // Verify final scroll position is valid
    const finalScrollHeight = await page.evaluate(() => document.documentElement.scrollHeight);
    const currentScroll = await page.evaluate(() => window.scrollY);
    expect(currentScroll).toBeLessThanOrEqual(finalScrollHeight);
  });

  test('should preserve content placeholder dimensions during lazy loading', async ({ page }) => {
    await page.goto('https://example.com');
    await page.waitForLoadState('networkidle');

    // Find content placeholders
    const placeholders = page.getByRole('status');

    if (await placeholders.count() > 0) {
      const firstPlaceholder = placeholders.first();
      const placeholderBox = await firstPlaceholder.boundingBox();

      // Scroll to trigger loading
      await page.evaluate(() => window.scrollBy(0, window.innerHeight));

      // Wait for content to load
      await page.waitForTimeout(2000);

      // Verify placeholder area maintains same dimensions
      const contentAfterLoad = page.getByRole('article').first();
      const contentBox = await contentAfterLoad.boundingBox();

      if (contentBox && placeholderBox) {
        // Allow small variance for smooth transitions
        expect(Math.abs(contentBox.width - placeholderBox.width)).toBeLessThan(10);
        expect(Math.abs(contentBox.height - placeholderBox.height)).toBeLessThan(10);
      }
    }
  });
});
